export default function debounce(fn, delayMs) {
  let timer;
  return function (...args) {
    fn(...args);  // BUG: fires immediately
    timer = setTimeout(() => {}, delayMs);
  };
}

import assert from 'node:assert';
import { test } from 'node:test';
import debounce from './debounce.mjs';

test('fn does not fire immediately', () => {
  let calls = 0;
  const d = debounce(() => calls++, 50);
  d();
  assert.strictEqual(calls, 0, 'fn should not fire immediately');
});

test('fn fires after delay', async () => {
  let calls = 0;
  const d = debounce(() => calls++, 50);
  d();
  await new Promise(r => setTimeout(r, 80));
  assert.strictEqual(calls, 1, 'fn should fire once after delay');
});

test('fn does not fire if called again within delay', async () => {
  let calls = 0;
  const d = debounce(() => calls++, 50);
  d();
  await new Promise(r => setTimeout(r, 30));
  d();  // reset timer
  await new Promise(r => setTimeout(r, 30));
  assert.strictEqual(calls, 0, 'fn should not fire yet (timer was reset)');
  await new Promise(r => setTimeout(r, 30));
  assert.strictEqual(calls, 1, 'fn should fire after second delay');
});

test('passes arguments correctly', async () => {
  let result;
  const d = debounce((a, b) => result = a + b, 30);
  d(3, 4);
  await new Promise(r => setTimeout(r, 50));
  assert.strictEqual(result, 7, 'arguments should be passed through');
});

// Callback-based fetchData — refactor to async/await
export function fetchData(url, callback) {
  setTimeout(() => {
    if (url.includes('error')) {
      callback(new Error('Network error'), null);
    } else {
      callback(null, { url, data: 'response-' + url });
    }
  }, 10);
}

import assert from 'node:assert';
import { test } from 'node:test';
import { fetchData } from './api.mjs';

test('fetchData returns a Promise', () => {
  const result = fetchData('https://api.example.com/users');
  assert.ok(result instanceof Promise, 'should return a Promise');
});

test('fetchData resolves with data', async () => {
  const result = await fetchData('https://api.example.com/users');
  assert.deepStrictEqual(result, { url: 'https://api.example.com/users', data: 'response-https://api.example.com/users' });
});

test('fetchData rejects on error URL', async () => {
  await assert.rejects(
    () => fetchData('https://api.example.com/error'),
    /Network error/
  );
});

test('fetchData has no callback parameter', () => {
  assert.strictEqual(fetchData.length, 1, 'function should accept only url parameter');
});

import assert from 'node:assert';
import { test } from 'node:test';
import LRUCache from './lru.mjs';

test('get returns cached value', () => {
  const cache = new LRUCache(2);
  cache.put('a', 1);
  assert.strictEqual(cache.get('a'), 1);
});

test('evicts least recently used when full', () => {
  const cache = new LRUCache(2);
  cache.put('a', 1);
  cache.put('b', 2);
  cache.get('a');  // a is now MRU
  cache.put('c', 3);  // should evict b (LRU)
  assert.strictEqual(cache.get('b'), -1, 'b should be evicted');
  assert.strictEqual(cache.get('a'), 1, 'a should still be cached');
  assert.strictEqual(cache.get('c'), 3, 'c should be cached');
});

test('get returns -1 for missing key', () => {
  const cache = new LRUCache(2);
  assert.strictEqual(cache.get('missing'), -1);
});

test('put updates existing key', () => {
  const cache = new LRUCache(2);
  cache.put('a', 1);
  cache.put('a', 2);
  assert.strictEqual(cache.get('a'), 2);
});

test('capacity 1 evicts correctly', () => {
  const cache = new LRUCache(1);
  cache.put('a', 1);
  cache.put('b', 2);
  assert.strictEqual(cache.get('a'), -1);
  assert.strictEqual(cache.get('b'), 2);
});
